/**
 * Biologically unsustainable marine fish stocks share ??? FAO SOFIA stock status.
 * Core question: What share of assessed fish stocks are fished at biologically
 * unsustainable levels, and is that share still rising?
 *
 * Vintage: FAO The State of World Fisheries and Aquaculture 2024 (SOFIA 2024),
 * reference year 2021 for the global stock-status series (445 aggregated stocks,
 * ~72% of global marine fisheries production).
 */

export type Confidence = "disclosed" | "derived" | "carried";

export const SOURCE_NOTE =
  "Marine fishery stock status from FAO The State of World Fisheries and Aquaculture 2024 (SOFIA), reference year 2021. Global shares treat each of ~445 monitored stocks equally (unweighted by catch). Landings-weighted sustainable share (76.9%) and regional area scores are FAO-disclosed. Historical path points are FAO SOFIA disclosed vintages; intermediate years marked derived/carried are interpolated from published Figure 18 endpoints and prior SOFIA editions (2018???2022). Overfished = biomass below the level that can produce MSY.";

export const SOFIA_2024_URL =
  "https://www.fao.org/publications/home/fao-flagship-publications/the-state-of-world-fisheries-and-aquaculture/en";
export const SOFIA_STATUS_URL =
  "https://www.fao.org/3/cd0683en/online/sofia/2024/status-of-fishery-resources.html";

/** Headline meters for cards, lede, and job ready line */
export const HEADLINE = {
  /** Share of assessed stocks fished at biologically unsustainable levels, 2021 */
  unsustainableSharePct: 37.7,
  /** Share within biologically sustainable levels, 2021 */
  sustainableSharePct: 62.3,
  /** Prior assessment year (SOFIA 2022 vintage) */
  priorYear: 2019,
  priorUnsustainableSharePct: 35.4,
  priorSustainableSharePct: 64.6,
  /** Percentage-point rise in unsustainable share, 2019???2021 */
  deltaPp2019to2021: 2.3,
  /** 1974 starting point */
  baselineYear: 1974,
  baselineUnsustainableSharePct: 10,
  /** Landings-weighted sustainable share of assessed catch, 2021 */
  landingsWeightedSustainablePct: 76.9,
  landingsWeightedUnsustainablePct: 23.1,
  /** Composition within sustainable bucket, 2021 */
  maximallySustainablyFishedPct: 50.5,
  underfishedPct: 11.8,
  /** Top-10 landing species stocks sustainable share */
  top10SustainablePct: 78.9,
  /** Major commercial tuna stocks sustainable share */
  tunaSustainablePct: 87,
  tunaUnsustainablePct: 13,
  tunaCatchFromHealthyPct: 99,
  assessedStockCount: 445,
  marineProductionCoveragePct: 72,
  /** Worst / best FAO major fishing areas by sustainable share */
