export type OceanFilter = "all" | AreaRow["ocean"];

export function areasByOcean(ocean: OceanFilter): AreaRow[] {
  if (ocean === "all") return AREA_ROWS;
  return AREA_ROWS.filter((a) => a.ocean === ocean);
}

export function trendForRange(
  fromYear: number,
  toYear: number = 2021,
): TrendPoint[] {
  return GLOBAL_TREND.filter((p) => p.year >= fromYear && p.year <= toYear);
}

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

