args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AREA_ROWS,
  BENCHMARK_ROWS,
  COMPOSITION_2021,
  DECADE_DELTAS,
  GLOBAL_TREND,
  HEADLINE,
  SOURCE_NOTE,
  areasByOcean,
  fmtPct,
  fmtPp,
  trendForRange,
  type OceanFilter,
} from "@/data/biologically-unsustainable-stocks-share-2026-data";

// viz-types: unsustainable share area+line, area horizontal bars, dual-lens comparison bars, composition donut, decade delta bars, landings??sustainability scatter | layout: default

type ViewId = "trend" | "areas" | "lenses" | "mix" | "scatter";
type TrendFrom = 1974 | 2000 | 2015;
type AreaMetric = "unsustainable" | "sustainable";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => {
          const active = o.id === value;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onChange(o.id)}
              className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              {o.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function BiologicallyUnsustainableStocksShare2026Dashboard() {
  const [view, setView] = useState<ViewId>("trend");
  const [trendFrom, setTrendFrom] = useState<TrendFrom>(1974);
  const [ocean, setOcean] = useState<OceanFilter>("all");
  const [areaMetric, setAreaMetric] = useState<AreaMetric>("unsustainable");

  const trendData = useMemo(() => trendForRange(trendFrom), [trendFrom]);
  const areaData = useMemo(() => {
    const rows = areasByOcean(ocean);
    return [...rows].sort((a, b) =>
      areaMetric === "unsustainable"
        ? b.unsustainablePct - a.unsustainablePct
        : b.sustainablePct - a.sustainablePct,
    );
  }, [ocean, areaMetric]);

  const scatterData = useMemo(
    () =>
      AREA_ROWS.filter((a) => a.landingsSharePct != null).map((a) => ({
        name: a.shortLabel,
        landingsSharePct: a.landingsSharePct!,
        sustainablePct: a.sustainablePct,
        unsustainablePct: a.unsustainablePct,
        fill: a.fill,
        z: (a.landingsSharePct ?? 5) * 8,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="biologically-unsustainable-stocks-share-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-cyan-950 p-5 text-white shadow-sm sm:p-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-cyan-300/90">
          FAO SOFIA stock status ?? marine assessed stocks
        </p>
        <h2 className="mt-1 text-xl font-bold tracking-tight sm:text-2xl">
          Biologically unsustainable stocks share
        </h2>
        <p className="mt-2 max-w-3xl text-sm text-slate-300">
          What share of assessed fish stocks are fished at biologically
          unsustainable levels, and is that share still rising? Unweighted stock
          count hit{" "}
          <span className="font-semibold text-rose-300">
            {fmtPct(HEADLINE.unsustainableSharePct)}
          </span>{" "}
          in 2021 ??? up {fmtPp(HEADLINE.deltaPp2019to2021)} from 2019 ??? while
          landings-weighted unsustainable share sits near{" "}
          <span className="font-semibold text-cyan-300">
            {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
          </span>
          .
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Unsustainable (2021)
            </p>
            <p className="text-xl font-bold text-rose-300">
              {fmtPct(HEADLINE.unsustainableSharePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              ?? vs 2019
            </p>
            <p className="text-xl font-bold text-amber-300">
              {fmtPp(HEADLINE.deltaPp2019to2021)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Landings-weighted unsust.
            </p>
            <p className="text-xl font-bold text-cyan-300">
              {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Since 1974
            </p>
            <p className="text-xl font-bold text-slate-100">
