  const trendData = useMemo(() => trendForRange(trendFrom), [trendFrom]);
  const areaData = useMemo(() => {
    const rows = areasByOcean(ocean);
    return [...rows].sort((a, b) =>
      areaMetric === "unsustainable"
        ? b.unsustainablePct - a.unsustainablePct
        : b.sustainablePct - a.sustainablePct,
    );
