/**
 * QA: biologically-unsustainable-stocks-share-2026
 * // viz-types: unsustainable share area+line, area horizontal bars, dual-lens comparison bars, composition donut, decade delta bars, landings??sustainability scatter | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  AREA_ROWS,
  BENCHMARK_ROWS,
  COMPOSITION_2021,
  GLOBAL_TREND,
  HEADLINE,
} from "../src/data/biologically-unsustainable-stocks-share-2026-data.ts";

assert.equal(HEADLINE.unsustainableSharePct, 37.7);
assert.equal(HEADLINE.sustainableSharePct, 62.3);
assert.equal(HEADLINE.priorUnsustainableSharePct, 35.4);
assert.equal(HEADLINE.deltaPp2019to2021, 2.3);
assert.equal(HEADLINE.baselineUnsustainableSharePct, 10);
assert.equal(HEADLINE.landingsWeightedSustainablePct, 76.9);
assert.equal(HEADLINE.landingsWeightedUnsustainablePct, 23.1);
assert.equal(HEADLINE.maximallySustainablyFishedPct, 50.5);
assert.equal(HEADLINE.underfishedPct, 11.8);
assert.equal(HEADLINE.top10SustainablePct, 78.9);
assert.equal(HEADLINE.tunaSustainablePct, 87);
assert.ok(AREA_ROWS.length >= 15);
assert.equal(AREA_ROWS.find((r) => r.id === "87")?.sustainablePct, 33.3);
assert.equal(AREA_ROWS.find((r) => r.id === "77")?.sustainablePct, 84.2);
assert.ok(GLOBAL_TREND.length >= 8);
assert.equal(GLOBAL_TREND.find((p) => p.year === 2021)?.unsustainablePct, 37.7);
assert.equal(BENCHMARK_ROWS.length, 4);
assert.ok(
  Math.abs(
    COMPOSITION_2021.reduce((s, r) => s + r.sharePct, 0) - 100,
  ) < 0.2,
);

const root = process.cwd();
const slug = "biologically-unsustainable-stocks-share-2026";
const markers = [
  "Biologically unsustainable stocks share",
  "What share of assessed fish stocks are fished at biologically unsustainable levels",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4184);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(
      '[data-viz="biologically-unsustainable-stocks-share-2026"]',
      { timeout: 20000 },
    );
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Long-run path");
    await clickBtn(page, "Since 2000");
    await clickBtn(page, "Since 2015");
    await clickBtn(page, "Since 1974");
    await clickBtn(page, "Fishing areas");
    await clickBtn(page, "Pacific");
    await clickBtn(page, "Sustainable %");
    await clickBtn(page, "Unsustainable %");
    await clickBtn(page, "All oceans");
    await clickBtn(page, "Count vs catch");
    await clickBtn(page, "2021 mix");
    await clickBtn(page, "Landings map");
    await clickBtn(page, "Long-run path");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page, { slug });
    if (audit.issues.length > 0) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    console.log("??? viz interaction audit");
    console.log(`??? QA passed for ${slug}`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

