"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AREA_ROWS,
  BENCHMARK_ROWS,
  COMPOSITION_2021,
  DECADE_DELTAS,
  GLOBAL_TREND,
  HEADLINE,
  SOURCE_NOTE,
  areasByOcean,
  fmtPct,
  fmtPp,
  trendForRange,
  type OceanFilter,
} from "@/data/biologically-unsustainable-stocks-share-2026-data";

// viz-types: unsustainable share area+line, area horizontal bars, dual-lens comparison bars, composition donut, decade delta bars, landings??sustainability scatter | layout: default

type ViewId = "trend" | "areas" | "lenses" | "mix" | "scatter";
type TrendFrom = 1974 | 2000 | 2015;
type AreaMetric = "unsustainable" | "sustainable";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => {
          const active = o.id === value;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onChange(o.id)}
              className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              {o.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function BiologicallyUnsustainableStocksShare2026Dashboard() {
  const [view, setView] = useState<ViewId>("trend");
  const [trendFrom, setTrendFrom] = useState<TrendFrom>(1974);
  const [ocean, setOcean] = useState<OceanFilter>("all");
  const [areaMetric, setAreaMetric] = useState<AreaMetric>("unsustainable");

  const trendData = useMemo(() => trendForRange(trendFrom), [trendFrom]);
  const areaData = useMemo(() => {
    const rows = areasByOcean(ocean);
    return [...rows].sort((a, b) =>
      areaMetric === "unsustainable"
        ? b.unsustainablePct - a.unsustainablePct
        : b.sustainablePct - a.sustainablePct,
    );
  }, [ocean, areaMetric]);

  const scatterData = useMemo(
    () =>
      AREA_ROWS.filter((a) => a.landingsSharePct != null).map((a) => ({
        name: a.shortLabel,
        landingsSharePct: a.landingsSharePct!,
        sustainablePct: a.sustainablePct,
        unsustainablePct: a.unsustainablePct,
        fill: a.fill,
        z: (a.landingsSharePct ?? 5) * 8,
      })),
    [],
  );

  return (
    <div
