                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="maximallyPct"
                    name="Maximally sustainable %"
                    stackId="a"
                    stroke="#0ea5e9"
                    fill="#7dd3fc"
