                  <Area
                    type="monotone"
                    dataKey="underfishedPct"
                    name="Underfished %"
                    stackId="a"
                    stroke="#059669"
                    fill="#6ee7b7"
                  />
                  <Area
                    type="monotone"
                    dataKey="unsustainablePct"
                    name="Unsustainable %"
                    stackId="a"
                    stroke="#e11d48"
                    fill="#fda4af"
