                <YAxis
                  type="number"
                  dataKey="sustainablePct"
                  name="Sustainable"
                  unit="%"
                  domain={[20, 90]}
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Sustainable stock %",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[80, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) =>
