      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="sr-only">
        {GLOBAL_TREND.length} trend points ?? {AREA_ROWS.length} fishing areas ??{" "}
        {BENCHMARK_ROWS.length} benchmark lenses
      </p>
    </div>
