"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AREA_ROWS,
  BENCHMARK_ROWS,
  COMPOSITION_2021,
  DECADE_DELTAS,
  GLOBAL_TREND,
  HEADLINE,
  SOURCE_NOTE,
  areasByOcean,
  fmtPct,
  fmtPp,
  trendForRange,
  type OceanFilter,
} from "@/data/biologically-unsustainable-stocks-share-2026-data";

// viz-types: unsustainable share area+line, area horizontal bars, dual-lens comparison bars, composition donut, decade delta bars, landings??sustainability scatter | layout: default

type ViewId = "trend" | "areas" | "lenses" | "mix" | "scatter";
type TrendFrom = 1974 | 2000 | 2015;
type AreaMetric = "unsustainable" | "sustainable";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => {
          const active = o.id === value;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onChange(o.id)}
              className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              {o.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function BiologicallyUnsustainableStocksShare2026Dashboard() {
  const [view, setView] = useState<ViewId>("trend");
  const [trendFrom, setTrendFrom] = useState<TrendFrom>(1974);
  const [ocean, setOcean] = useState<OceanFilter>("all");
  const [areaMetric, setAreaMetric] = useState<AreaMetric>("unsustainable");

  const trendData = useMemo(() => trendForRange(trendFrom), [trendFrom]);
  const areaData = useMemo(() => {
    const rows = areasByOcean(ocean);
    return [...rows].sort((a, b) =>
      areaMetric === "unsustainable"
        ? b.unsustainablePct - a.unsustainablePct
        : b.sustainablePct - a.sustainablePct,
    );
  }, [ocean, areaMetric]);

  const scatterData = useMemo(
    () =>
      AREA_ROWS.filter((a) => a.landingsSharePct != null).map((a) => ({
        name: a.shortLabel,
        landingsSharePct: a.landingsSharePct!,
        sustainablePct: a.sustainablePct,
        unsustainablePct: a.unsustainablePct,
        fill: a.fill,
        z: (a.landingsSharePct ?? 5) * 8,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="biologically-unsustainable-stocks-share-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-cyan-950 p-5 text-white shadow-sm sm:p-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-cyan-300/90">
          FAO SOFIA stock status ?? marine assessed stocks
        </p>
        <h2 className="mt-1 text-xl font-bold tracking-tight sm:text-2xl">
          Biologically unsustainable stocks share
        </h2>
        <p className="mt-2 max-w-3xl text-sm text-slate-300">
          What share of assessed fish stocks are fished at biologically
          unsustainable levels, and is that share still rising? Unweighted stock
          count hit{" "}
          <span className="font-semibold text-rose-300">
            {fmtPct(HEADLINE.unsustainableSharePct)}
          </span>{" "}
          in 2021 ??? up {fmtPp(HEADLINE.deltaPp2019to2021)} from 2019 ??? while
          landings-weighted unsustainable share sits near{" "}
          <span className="font-semibold text-cyan-300">
            {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
          </span>
          .
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Unsustainable (2021)
            </p>
            <p className="text-xl font-bold text-rose-300">
              {fmtPct(HEADLINE.unsustainableSharePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              ?? vs 2019
            </p>
            <p className="text-xl font-bold text-amber-300">
              {fmtPp(HEADLINE.deltaPp2019to2021)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Landings-weighted unsust.
            </p>
            <p className="text-xl font-bold text-cyan-300">
              {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Since 1974
            </p>
            <p className="text-xl font-bold text-slate-100">
              {fmtPct(HEADLINE.baselineUnsustainableSharePct)} ???{" "}
              {fmtPct(HEADLINE.unsustainableSharePct)}
            </p>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
        <ToggleGroup
          label="Panel"
          value={view}
          onChange={setView}
          options={[
            { id: "trend", label: "Long-run path" },
            { id: "areas", label: "Fishing areas" },
            { id: "lenses", label: "Count vs catch" },
            { id: "mix", label: "2021 mix" },
            { id: "scatter", label: "Landings map" },
          ]}
        />
        {view === "trend" && (
          <ToggleGroup
            label="From"
            value={String(trendFrom)}
            onChange={(v) => setTrendFrom(Number(v) as TrendFrom)}
            options={[
              { id: "1974", label: "Since 1974" },
              { id: "2000", label: "Since 2000" },
              { id: "2015", label: "Since 2015" },
            ]}
          />
        )}
        {view === "areas" && (
          <>
            <ToggleGroup
              label="Ocean"
              value={ocean}
              onChange={setOcean}
              options={[
                { id: "all", label: "All oceans" },
                { id: "Atlantic", label: "Atlantic" },
                { id: "Pacific", label: "Pacific" },
                { id: "Indian", label: "Indian" },
                { id: "Mediterranean", label: "Med. & Black" },
              ]}
            />
            <ToggleGroup
              label="Metric"
              value={areaMetric}
              onChange={setAreaMetric}
              options={[
                { id: "unsustainable", label: "Unsustainable %" },
                { id: "sustainable", label: "Sustainable %" },
              ]}
            />
          </>
        )}
      </div>

      {view === "trend" && (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Unsustainable stock share, 1974???2021"
              subtitle="Equal-weight stock count ?? FAO SOFIA path"
            >
              <div className="h-[340px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={trendData}
                    margin={{ top: 8, right: 12, left: 0, bottom: 0 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                    <YAxis
                      domain={[0, 45]}
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <Tooltip
                      formatter={(v) => fmtPct(Number(v))}
                      labelFormatter={(l) => `Year ${l}`}
                    />
                    <Legend />
                    <Area
                      type="monotone"
                      dataKey="unsustainablePct"
                      name="Unsustainable %"
                      fill="#fda4af"
                      stroke="#f43f5e"
                      fillOpacity={0.35}
                    />
                    <Line
                      type="monotone"
                      dataKey="sustainablePct"
                      name="Sustainable %"
                      stroke="#0ea5e9"
                      strokeWidth={2}
                      dot={{ r: 3 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title="Pace by era"
              subtitle="?? unsustainable share (percentage points)"
            >
              <div className="h-[340px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={DECADE_DELTAS}
                    margin={{ top: 8, right: 8, left: 0, bottom: 24 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      dataKey="label"
                      tick={{ fontSize: 10 }}
                      interval={0}
                    />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}`}
                    />
                    <Tooltip
                      formatter={(v, name) => {
                        const n = Number(v);
                        return name === "annualizedPp"
                          ? [`${n.toFixed(2)} pp/yr`, "Annualized"]
                          : [`${n.toFixed(1)} pp`, "Total ??"];
                      }}
                    />
                    <Bar
                      dataKey="deltaPp"
                      name="Total ??"
                      fill="#f43f5e"
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="annualizedPp"
                      name="pp / year"
                      fill="#fb923c"
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {view === "areas" && (
        <ChartCard
          title={
            areaMetric === "unsustainable"
              ? "Unsustainable stock share by FAO major fishing area"
              : "Sustainable stock share by FAO major fishing area"
          }
          subtitle="2021 ?? filter by ocean basin ?? sorted by selected metric"
        >
          <div className="h-[480px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={areaData}
                layout="vertical"
                margin={{ top: 4, right: 24, left: 8, bottom: 4 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 100]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <YAxis
                  type="category"
                  dataKey="shortLabel"
                  width={118}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(v) => fmtPct(Number(v))}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.label ?? ""
                  }
                />
                <Bar
                  dataKey={
                    areaMetric === "unsustainable"
                      ? "unsustainablePct"
                      : "sustainablePct"
                  }
                  name={
                    areaMetric === "unsustainable"
                      ? "Unsustainable %"
                      : "Sustainable %"
                  }
                  radius={[0, 4, 4, 0]}
                >
                  {areaData.map((row) => (
                    <Cell key={row.id} fill={row.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "lenses" && (
        <ChartCard
          title="Count-based vs catch-weighted lenses"
          subtitle="Same ocean, different weights ??? why 37.7% and 23.1% can both be true"
        >
