          in 2021 ??? up {fmtPp(HEADLINE.deltaPp2019to2021)} from 2019 ??? while
          landings-weighted unsustainable share sits near{" "}
          <span className="font-semibold text-cyan-300">
            {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
          </span>
          .
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Unsustainable (2021)
            </p>
            <p className="text-xl font-bold text-rose-300">
              {fmtPct(HEADLINE.unsustainableSharePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              ?? vs 2019
            </p>
            <p className="text-xl font-bold text-amber-300">
              {fmtPp(HEADLINE.deltaPp2019to2021)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Landings-weighted unsust.
            </p>
            <p className="text-xl font-bold text-cyan-300">
              {fmtPct(HEADLINE.landingsWeightedUnsustainablePct)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2 ring-1 ring-white/10">
            <p className="text-[10px] uppercase tracking-wide text-slate-400">
              Since 1974
            </p>
            <p className="text-xl font-bold text-slate-100">
              {fmtPct(HEADLINE.baselineUnsustainableSharePct)} ???{" "}
              {fmtPct(HEADLINE.unsustainableSharePct)}
            </p>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
        <ToggleGroup
          label="Panel"
          value={view}
          onChange={setView}
          options={[
            { id: "trend", label: "Long-run path" },
            { id: "areas", label: "Fishing areas" },
            { id: "lenses", label: "Count vs catch" },
            { id: "mix", label: "2021 mix" },
            { id: "scatter", label: "Landings map" },
          ]}
        />
        {view === "trend" && (
          <ToggleGroup
            label="From"
            value={String(trendFrom)}
            onChange={(v) => setTrendFrom(Number(v) as TrendFrom)}
            options={[
              { id: "1974", label: "Since 1974" },
              { id: "2000", label: "Since 2000" },
              { id: "2015", label: "Since 2015" },
            ]}
          />
        )}
        {view === "areas" && (
          <>
            <ToggleGroup
              label="Ocean"
              value={ocean}
              onChange={setOcean}
              options={[
                { id: "all", label: "All oceans" },
                { id: "Atlantic", label: "Atlantic" },
                { id: "Pacific", label: "Pacific" },
                { id: "Indian", label: "Indian" },
                { id: "Mediterranean", label: "Med. & Black" },
              ]}
            />
            <ToggleGroup
              label="Metric"
              value={areaMetric}
              onChange={setAreaMetric}
              options={[
