              title="Unsustainable stock share, 1974???2021"
              subtitle="Equal-weight stock count ?? FAO SOFIA path"
            >
              <div className="h-[340px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={trendData}
                    margin={{ top: 8, right: 12, left: 0, bottom: 0 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                    <YAxis
                      domain={[0, 45]}
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <Tooltip
                      formatter={(v) => fmtPct(Number(v))}
                      labelFormatter={(l) => `Year ${l}`}
                    />
                    <Legend />
                    <Area
                      type="monotone"
                      dataKey="unsustainablePct"
                      name="Unsustainable %"
                      fill="#fda4af"
                      stroke="#f43f5e"
                      fillOpacity={0.35}
                    />
                    <Line
                      type="monotone"
                      dataKey="sustainablePct"
                      name="Sustainable %"
                      stroke="#0ea5e9"
                      strokeWidth={2}
                      dot={{ r: 3 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title="Pace by era"
              subtitle="?? unsustainable share (percentage points)"
            >
              <div className="h-[340px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={DECADE_DELTAS}
                    margin={{ top: 8, right: 8, left: 0, bottom: 24 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      dataKey="label"
                      tick={{ fontSize: 10 }}
                      interval={0}
                    />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}`}
                    />
                    <Tooltip
                      formatter={(v, name) => {
                        const n = Number(v);
                        return name === "annualizedPp"
                          ? [`${n.toFixed(2)} pp/yr`, "Annualized"]
                          : [`${n.toFixed(1)} pp`, "Total ??"];
                      }}
                    />
                    <Bar
                      dataKey="deltaPp"
                      name="Total ??"
                      fill="#f43f5e"
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="annualizedPp"
                      name="pp / year"
                      fill="#fb923c"
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {view === "areas" && (
        <ChartCard
          title={
            areaMetric === "unsustainable"
              ? "Unsustainable stock share by FAO major fishing area"
              : "Sustainable stock share by FAO major fishing area"
          }
          subtitle="2021 ?? filter by ocean basin ?? sorted by selected metric"
        >
          <div className="h-[480px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={areaData}
                layout="vertical"
                margin={{ top: 4, right: 24, left: 8, bottom: 4 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 100]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <YAxis
                  type="category"
                  dataKey="shortLabel"
                  width={118}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(v) => fmtPct(Number(v))}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.label ?? ""
                  }
                />
                <Bar
                  dataKey={
                    areaMetric === "unsustainable"
                      ? "unsustainablePct"
                      : "sustainablePct"
                  }
                  name={
                    areaMetric === "unsustainable"
                      ? "Unsustainable %"
                      : "Sustainable %"
                  }
                  radius={[0, 4, 4, 0]}
                >
                  {areaData.map((row) => (
                    <Cell key={row.id} fill={row.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "lenses" && (
        <ChartCard
          title="Count-based vs catch-weighted lenses"
          subtitle="Same ocean, different weights ??? why 37.7% and 23.1% can both be true"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={BENCHMARK_ROWS}
                margin={{ top: 8, right: 12, left: 0, bottom: 48 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="label"
                  tick={{ fontSize: 11 }}
                  interval={0}
                  angle={-18}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  domain={[0, 100]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <Tooltip formatter={(v) => fmtPct(Number(v))} />
                <Legend />
                <Bar
                  dataKey="unsustainablePct"
                  name="Unsustainable %"
                  fill="#f43f5e"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="sustainablePct"
                  name="Sustainable %"
                  fill="#0ea5e9"
                  radius={[4, 4, 0, 0]}
                />
