      )}

      {view === "mix" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="2021 composition of assessed stocks"
            subtitle="Underfished ?? maximally sustainable ?? unsustainable"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
