                    nameKey="shortLabel"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                    label={(props) => {
                      const p = props as {
                        shortLabel?: string;
                        sharePct?: number;
                        name?: string;
                        value?: number;
                      };
                      const label = p.shortLabel ?? p.name ?? "";
                      const pct = p.sharePct ?? p.value ?? 0;
                      return `${label} ${fmtPct(Number(pct))}`;
                    }}
                  >
                    {COMPOSITION_2021.map((row) => (
                      <Cell key={row.id} fill={row.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="What moved inside the sustainable bucket"
            subtitle="Maximally fished fell; underfished bounced 2019???2021"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart
                  data={GLOBAL_TREND.filter(
                    (p) => p.maximallyPct != null && p.underfishedPct != null,
                  )}
                  margin={{ top: 8, right: 12, left: 0, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 70]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="maximallyPct"
                    name="Maximally sustainable %"
                    stackId="a"
                    stroke="#0ea5e9"
                    fill="#7dd3fc"
                  />
                  <Area
                    type="monotone"
                    dataKey="underfishedPct"
                    name="Underfished %"
                    stackId="a"
                    stroke="#059669"
                    fill="#6ee7b7"
                  />
                  <Area
                    type="monotone"
                    dataKey="unsustainablePct"
                    name="Unsustainable %"
                    stackId="a"
                    stroke="#e11d48"
                    fill="#fda4af"
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Landing weight vs sustainability score"
          subtitle="Areas with disclosed world landing shares ??? bubble size ??? landing weight"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="landingsSharePct"
                  name="Landings share"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Share of global marine landings (%)",
                    position: "insideBottom",
                    offset: -2,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="sustainablePct"
                  name="Sustainable"
                  unit="%"
                  domain={[20, 90]}
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Sustainable stock %",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[80, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) => {
                    const label = String(name ?? "");
                    return label.includes("Landings") ||
                      label.includes("Sustainable")
                      ? fmtPct(Number(v))
                      : Number(v);
                  }}
                  labelFormatter={(_, p) => p?.[0]?.payload?.name ?? ""}
                />
                <Scatter name="FAO area" data={scatterData}>
                  {scatterData.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Southeast Pacific pairs a weak stock-count score ({fmtPct(33.3)}{" "}
            sustainable) with heavy anchoveta landings; Northwest Pacific
            combines ~{fmtPct(23.8, 1)} of world landings with only{" "}
            {fmtPct(44)} sustainable stocks.
          </p>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="sr-only">
        {GLOBAL_TREND.length} trend points ?? {AREA_ROWS.length} fishing areas ??{" "}
        {BENCHMARK_ROWS.length} benchmark lenses
      </p>
    </div>
  );
}

